def solve(n: int, m: int, L: int, S: list[int], theta: float) -> QuantumCircuit:
    x, y = QuantumRegister(n), QuantumRegister(m)
    qc = QuantumCircuit(x, y)

    # Compute f(x) into y[0]
    for i in range(n):
        if S[i] == 0:
            continue
        if i == 0:
            qc.cp(2 * theta * S[i], x[0], y[0])
        else:
            qc.append(qc.cp(2 * theta * S[i]).control(1), [x[i]] + [x[i-1]] + [y[0]])

    # Add -f(x) to y[0]
    if L != 0:
        for i in range(n):
            if i == 0:
                qc.cp(-2 * theta * L, x[0], y[0])
            else:
                qc.append(qc.cp(-2 * theta * L).control(1), [x[i]] + [x[i-1]] + [y[0]])

    # Apply phase if f(x) == L (mod 2^m)
    qc.mcp(2 * theta, x, y[0])

    return qc

